<script setup lang="ts">
import {ref, reactive, onMounted, inject} from 'vue'
import {X} from 'lucide-vue-next'
import {api, session, date, label, describeError, type Data} from '../api'
const props=defineProps<{activity:Data}>(),emit=defineEmits(['close']),notify=inject<(s:string,e?:boolean)=>void>('notify')!
const grant=ref<Data|null>(null),error=ref(''),busy=ref(false),form=reactive({completion:'COMPLETED',experience:5,reason:''}),ratings=reactive<Record<string,{enabled:boolean,score:number,comment:string}>>({})
async function load(){try{grant.value=await api(`/activities/${props.activity.id}/feedback`);for(const m of grant.value!.members)if(m.userId!==session.user?.id)ratings[m.userId]={enabled:false,score:5,comment:''}}catch(e){error.value=describeError(e)}}
onMounted(load)
async function submit(){busy.value=true;error.value='';try{await api(`/activities/${props.activity.id}/feedback`,'POST',{...form,ratings:Object.entries(ratings).filter(([,v])=>v.enabled).map(([id,v])=>({targetUserId:id,score:v.score,comment:v.comment}))});notify('反馈已记录，感谢认真完成这次行动');await load()}catch(e){error.value=describeError(e)}finally{busy.value=false}}
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="feedback-title"><button class="modal-close icon-button" aria-label="关闭反馈" @click="emit('close')"><X/></button><span class="eyebrow">LOOK BACK, MOVE FORWARD</span><h2 id="feedback-title">这次同行，感觉如何？</h2><p class="muted">{{activity.title}}</p><div v-if="error" class="error-box" role="alert">{{error}}</div><template v-if="grant"><p class="field-help">结束于 {{date(grant.endedAt)}}，结束后24小时内可提交一次反馈。</p><div v-if="grant.feedback" class="success-box">你已提交反馈：{{label(grant.feedback.completion)}} · 体验 {{grant.feedback.experience}} / 5。每场活动只能提交一次。</div><form v-else class="stack" @submit.prevent="submit"><div class="form-grid"><label>目标完成情况<select v-model="form.completion"><option value="COMPLETED">已完成</option><option value="PARTIAL">部分完成</option><option value="NOT_COMPLETED">未完成</option></select></label><label>组队体验<select v-model.number="form.experience"><option v-for="n in [5,4,3,2,1]" :key="n" :value="n">{{n}} 分</option></select></label><label class="full">{{form.completion==='COMPLETED'?'补充说明（可选）':'未完成原因（必填）'}}<textarea v-model="form.reason" :required="form.completion!=='COMPLETED'" maxlength="500"></textarea></label></div><h3>同行成员评价（自愿）</h3><template v-for="m in grant.members" :key="m.userId"><div v-if="ratings[m.userId]" class="panel stack"><label class="check-label"><input v-model="ratings[m.userId]!.enabled" type="checkbox"/>评价 {{m.nickname}}</label><div v-if="ratings[m.userId]!.enabled" class="form-grid"><label>相处体验<select v-model.number="ratings[m.userId]!.score"><option v-for="n in [5,4,3,2,1]" :key="n" :value="n">{{n}} 分</option></select></label><label>评价说明<input v-model="ratings[m.userId]!.comment" maxlength="300"/></label></div></div></template><p class="field-help">评价只记录个人体验，不会自动判定他人失约。如有争议，请通过举报与申诉处理。</p><div class="modal-actions"><button class="primary" :disabled="busy">{{busy?'提交中…':'提交本次反馈'}}</button></div></form></template></section></div></template>
